import logging
from .template import render_template_to_file
from .iperf import build_iperf_client_command
from taf.ue.tm500.rci import rci
from taf.transport.ssh import ssh


class runner(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.tm500 = rci()
        self.csn = ssh()
        self.pid_uplink = None
        self.pid_downlink = None

    def ue_attach(self, middle_cell_freq, imsi, log_path, tm500_alias=None, rfrx_gain=-30, mcc_mnc=55510,
                  physical_cell_id=307, mnc_length=3, authentication_key='00112233445566778899AABBCCDDEEFF',
                  milenage_op_key='0ED47545168EAFE2C39C075829A7B61F'):
        """
        This keyword generate scripts based on provided variables.
        For more details about variables see `TM500 command reference
        <https://confluence.int.net.nokia.com/display/CV/Automation+CWR?preview=/489894279/489894264/TM500LTE_CommandReference.pdf>`

        :param middle_cell_freq: Downlink carrier frequency
        :param imsi: either value set in epcsim or see
        `Confluence page <https://confluence.int.net.nokia.com/pages/viewpage.action?pageId=514160999>`_ for real core
        :param log_path: Path to your local directory with log files
        :param tm500_alias: alias to tm500 connection created by ta.ue.tm500.rci
        :param rfrx_gain: Expected received singal power for antenna 1 and 2 in dBm
        :param mcc_mnc: Mobile Country Code followed by Mobile Network Code. 5-6 decimal digits.
        :param physical_cell_id: physical cell id
        :param middle_cell_freq: Downlink carrier frequency
        :param imsi: either value set in epcsim or see
        `Confluence page <https://confluence.int.net.nokia.com/pages/viewpage.action?pageId=514160999>`
        for real core
        :param mnc_length: Length of mnc in digits
        :param authentication_key: either value set in epcsim or see
        `Confluence page <https://confluence.int.net.nokia.com/pages/viewpage.action?pageId=514160999>`
        for real core (field KI)
        :param milenage_op_key: either value set in epcsim or see
        `Confluence page <https://confluence.int.net.nokia.com/pages/viewpage.action?pageId=514160999>`
        for real core (field OPC)
        :return: attach script response
        """
        template_dir = "tm500_scripts_templates"
        render_template_to_file(
            template_dir + "/Cell_Search_MIB_decoding_3rdGen_rc.txt.j2",
            log_path + "/Cell_Search_MIB_decoding_3rdGen_rc.txt",
            rfrx_gain=rfrx_gain, mcc_mnc=mcc_mnc,
            physical_cell_id=physical_cell_id,
            middle_cell_freq=middle_cell_freq)
        render_template_to_file(template_dir + "/UE_Attach_3rdGen_rc.txt.j2",
                                log_path + "/UE_Attach_3rdGen_rc.txt",
                                imsi=imsi,
                                mnc_length=mnc_length,
                                authentication_key=authentication_key,
                                milenage_op_key=milenage_op_key,
                                middle_cell_freq=middle_cell_freq,
                                physical_cell_id=physical_cell_id,
                                mcc_mnc=mcc_mnc)

        return self.ue_custom_attach(tm500_alias,
                                     template_dir + "/NAS_mode_config.txt",
                                     log_path + "/Cell_Search_MIB_decoding_3rdGen_rc.txt",
                                     log_path + "/UE_Attach_3rdGen_rc.txt")

    def ue_detach(self, tm500_alias, detach_script_path=None):
        """
        Detach TM500. Allows to provide custom scripts for detach
        and it this case user is responsible for setting proper variables
        in script. If detach_script_path was not provided default value is used.
        """
        detach_script_path = detach_script_path or "tm500_scripts_templates/detach.txt"
        self.tm500.send_script(detach_script_path, alias=tm500_alias)

    def ue_custom_attach(self, tm500_alias, hw_connect_script_path,
                         cell_search_script_path, attach_script_path):
        """
        Allows to provide custom scripts for:
          * hardware connection, cell search, attach, and detach.
          * User is responsible for setting proper variables in scripts

        :param tm500_alias: tm500 connection alias
        :param hw_connect_script_path: Path to hardware connection script
        :param cell_search_script_path: Path to cell search script
        :param attach_script_path: Path to attach script
        :return: attach response
        """
        logging.info("Sending hw_connect_script from {script_path}".format(
            script_path=hw_connect_script_path))
        self.tm500.send_script(hw_connect_script_path, tm500_alias)

        logging.info("Sending cell_search_script from {script_path}".format(
            script_path=cell_search_script_path))
        self.tm500.send_script(cell_search_script_path, tm500_alias)

        logging.info("Sending attach_script from {script_path}".format(
            script_path=attach_script_path))
        response = self.tm500.send_script(attach_script_path, tm500_alias)
        return response

    @staticmethod
    def evaluate_attach_response(response):
        """ Asserts that  messages "Random Access Complete" and
        "Attach Result: EPS Only" are present in attach response.

        :param response: Attach response
        :raise: AssertionError """
        assert "Random Access Complete" in response, "{} was not present in {}".format(
            "Random Access Complete", response)
        assert "Attach Result: EPS Only" in response, "{} was not present in {}".format(
            "Attach Result: EPS Only", response)

    def traffic_start(self, iperf, data_transfer_params, direction='uplink'):
        """
        Performs data transfer test. Assumes iperf is installed and networks are configured.

        :param iperf: ssh connection to iperf responsible for downlink (AppServer) or uplink (COBHAM VM)
        :param direction: Type of connection - 'uplink' or 'downlink'
        """
        self._check_direction(direction)
        dir_cmd = build_iperf_client_command(
            server_ip=data_transfer_params[direction]['server_ip'], udp=True,
            port=data_transfer_params[direction]['port'],
            bitrate=data_transfer_params[direction]['bitrate'] + "M",
            transmission_time=-1,
            interval=1, buf_length=data_transfer_params[direction]['buf_length'])
        self.csn.send_command(dir_cmd, connection=iperf)
        pid = self.csn.read_output_until('\n')
        self._set_pid(pid, direction)

    @staticmethod
    def _check_direction(direction):
        correct = {'uplink', 'downlink'}
        if direction not in correct:
            exc_msg = ("Unrecognized direction: '{}'. Please use either "
                       "'uplink' or 'downlink'.")
            raise TypeError(exc_msg.format(direction))

    def _set_pid(self, pid, direction):
        direction = direction.lower()
        if direction == 'uplink':
            self.pid_uplink = pid
        elif direction == 'downlink':
            self.pid_downlink = pid

    def get_throughput(self, direction='uplink'):
        """
        Provide throughput from traffic

        :param dir: Type of connection - 'uplink' or 'downlink'
        """
        self._check_direction(direction)
        throughput_dict = self._read_sar_output()
        interface = 'backhaul' if direction.lower() == 'uplink' else 'fronthaul'
        return float(throughput_dict[interface]['txkB/s'])

    def traffic_stop(self, iperf, direction='uplink'):
        self._check_direction(direction)
        pid = self._get_pid(direction)
        self.csn.execute('kill {}'.format(pid), connection=iperf)

    def _get_pid(self, direction):
        direction = direction.lower()
        if direction == 'uplink':
            return self.pid_uplink
        elif direction == 'downlink':
            return self.pid_downlink

    def _read_sar_output(self, interval=1, count=600):
        """
        Runs sar on UEUP and returns output in form of 2D table.

        :param interval: sar interval (in seconds). Default 1
        :param count: sar counter. Default 600
        :return:
        """
        sar_command = r'sar -n DEV {interval} {count} | grep Average | sed -e "s/\s\+/,/g" | sed -e "s/Average:,//g"'\
            .format(interval=interval, count=count)
        self.csn.send_command(sar_command, connection="UEUP")
        result_csv = self.csn.read_output(connection="UEUP")
        throughput_dict = self._convert_throughput_csv_to_dict(result_csv)
        return throughput_dict

    @staticmethod
    def _convert_throughput_csv_to_dict(csv_output):
        table = [l.split(",") for l in csv_output.splitlines()]
        header, data = table[0], table[1:]
        dictionary = {row[0]: dict(zip(header[1:], row[1:])) for row in data}
        return dictionary
